mapper.select:
SELECT so.*, m.nickname AS member_nickname
FROM sales_order so
LEFT JOIN member m ON m.member_id = so.member_id


        AND so.created_at >= #{from}


        AND so.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)


        AND so.payment_status = #{status}


        AND so.member_id = #{memberId}


        AND (so.order_no LIKE CONCAT('%', #{keyword}, '%')
             OR m.nickname LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY so.created_at DESC, so.sales_order_id DESC
